@import url('https://fonts.googleapis.com/css2?family=M+PLUS+Rounded+1c:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Nintendo DNA — joy red on toy white, rounded delight */
.theme-nintendo-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.970 0 0);
  --surface-2: oklch(0.943 0 0);
  --fg: oklch(0.402 0 0);
  --fg-muted: oklch(0.633 0 0);
  --accent: oklch(0.581 0.238 27.9);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.730 0.136 223.7);
  --line: oklch(0.922 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.654 0.232 30.2);
  --radius: 1rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "M PLUS Rounded 1c", sans-serif;
  --font-body: "M PLUS Rounded 1c", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.03em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-nintendo-dna h1,
.theme-nintendo-dna h2,
.theme-nintendo-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-nintendo-dna { --font-ui: var(--font-display); }
.theme-nintendo-dna button { font-weight: 700; transition: transform 140ms cubic-bezier(0.34, 1.56, 0.64, 1); }
.theme-nintendo-dna button:active { transform: scale(0.92); }
.theme-nintendo-dna h1 { font-weight: 800; }
.theme-nintendo-dna h1::after { content: ""; display: block; height: 5px; width: 6rem; margin-top: 0.6rem; border-radius: 999px; background: linear-gradient(90deg, #ff3c28 0 50%, #0ab9e6 50% 100%); }

/* depth */
.theme-nintendo-dna { background-image: radial-gradient(oklch(0.402 0 0 / 4%) 1.5px, transparent 1.5px); background-size: 26px 26px; }
.theme-nintendo-dna thead th { font-size: 0.74rem; font-weight: 800; color: var(--accent-2); border-bottom: 3px solid var(--accent-2); border-radius: 2px; }
.theme-nintendo-dna tbody td { border-bottom: 1px solid var(--line); }
.theme-nintendo-dna tbody tr:hover td { background: color-mix(in oklab, var(--accent) 6%, transparent); }
.theme-nintendo-dna a { color: var(--accent-2); font-weight: 700; text-underline-offset: 3px; }
.theme-nintendo-dna a:hover { text-decoration-style: wavy; text-decoration-color: var(--accent); }
.theme-nintendo-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-nintendo-dna input, .theme-nintendo-dna select { border-radius: var(--radius-pill); }
.theme-nintendo-dna input:focus-visible, .theme-nintendo-dna select:focus-visible, .theme-nintendo-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 4px color-mix(in oklab, var(--accent) 25%, transparent); }
.theme-nintendo-dna button { box-shadow: 0 3px 0 color-mix(in oklab, var(--fg) 22%, transparent); }
.theme-nintendo-dna button:active { box-shadow: 0 1px 0 color-mix(in oklab, var(--fg) 22%, transparent); }
.theme-nintendo-dna kbd { font-family: var(--font-display); font-weight: 800; font-size: 0.75em; padding: 0.18em 0.6em; border-radius: 999px; background: oklch(0.300 0 0); color: oklch(0.98 0 0); box-shadow: 0 2px 0 oklch(0.180 0 0); }
.theme-nintendo-dna ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-nintendo-dna ::-webkit-scrollbar-track { background: var(--surface-2); border-radius: 999px; }
.theme-nintendo-dna ::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 999px; border: 3px solid var(--surface-2); }
.theme-nintendo-dna .label-caps { color: var(--accent); font-weight: 800; }
.theme-nintendo-dna .themed-border { border-color: color-mix(in oklab, var(--accent-2) 50%, var(--line)); }

/* alt mode: Switch dark — #2d2d2d console shell, neon Joy-Con accents */
.theme-nintendo-dna.alt-mode {
  --bg: oklch(0.280 0.000 0.0);
  --surface: oklch(0.330 0.000 0.0);
  --surface-2: oklch(0.385 0.000 0.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.75 0.01 90);
  --accent: oklch(0.660 0.220 31.0);
  --accent-2: oklch(0.730 0.130 220.0);
  --line: oklch(1 0 0 / 16%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image: radial-gradient(oklch(1 0 0 / 4%) 1.5px, transparent 1.5px);
  background-size: 26px 26px;
}
.theme-nintendo-dna.alt-mode kbd { background: oklch(0.96 0 0); color: oklch(0.25 0 0); box-shadow: 0 2px 0 oklch(0.70 0 0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
